const D = { energy: .6, scale: 1, density: .5, speed: 1, jitter: .3, hue: 190, x: .5, y: .5, style: 'skeletal', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const st = P.style, u = Math.min(width, height);
const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7) * 43758.5453; return s - Math.floor(s); };
const H = ((P.hue%360)+360)%360;

// style palette
let bond, arom, cloud, carbon, groundV, paper;
if (st === 'orbital')      { bond=[H,40,60,26]; arom=[H+30,70,80]; cloud=[H,80,70]; carbon=[H,20,95]; groundV=8; paper=false; }
else if (st === 'blueprint'){ bond=[200,70,80,60]; arom=[196,60,90]; cloud=[200,50,40]; carbon=[200,20,98]; groundV=12; paper=false; }
else if (st === 'ink')     { bond=[28,25,18,80]; arom=[20,30,30]; cloud=[30,25,45]; carbon=[24,30,14]; groundV=52; paper=true; }
else if (st === 'neon')    { bond=[H,90,95,70]; arom=[(H+140)%360,90,95]; cloud=[H,95,80]; carbon=[0,0,100]; groundV=6; paper=false; }
else /* skeletal */        { bond=[H,55,88,60]; arom=[42,80,92]; cloud=[H,70,60]; carbon=[0,0,96]; groundV=7; paper=false; }

// hex angles (flat-top)
const CA = [], SA = [];
for (let k = 0; k < 6; k++) { const a = k*Math.PI/3; CA.push(Math.cos(a)); SA.push(Math.sin(a)); }

// honeycomb lattice (seeded), rebuilt on size/scale/seed
const R = u*(0.075 + 0.06*P.scale);
const dxc = 1.5*R, dyc = Math.sqrt(3)*R;
const lkey = width+'x'+height+'|'+P.seed+'|'+R.toFixed(1);
if (S.lkey !== lkey) {
  S.lkey = lkey; S.hex = [];
  const cols = Math.ceil(width/dxc)+3, rows = Math.ceil(height/dyc)+3;
  for (let ci = -1; ci < cols; ci++) for (let ri = -1; ri < rows; ri++) {
    const cx = ci*dxc, cy = ri*dyc + (ci&1 ? dyc*0.5 : 0);
    const jx = (fr(ci*7.1+ri*3.3)-0.5), jy = (fr(ci*2.7+ri*9.1)-0.5);
    S.hex.push({ cx, cy, jx, jy, ph: fr(ci*4.3+ri*1.9)*6.28, kx: 0.5+fr(ci+ri*3)*0.5 });
  }
}

const kek = K.t*(0.5 + P.speed*0.8);                     // resonance flip rate
const wt = K.t*(0.6 + P.speed*0.5);                      // aromaticity wave rate
const jit = P.jitter * R*0.5;
const driftx = Math.sin(K.t*0.19)*R*0.5 + Math.sin(K.t*0.41+1.0)*R*0.25;
const drifty = Math.cos(K.t*0.23+0.5)*R*0.5 + Math.sin(K.t*0.31+2.1)*R*0.25;
const bw = Math.max(1, u*0.0022*(0.7+P.energy*0.9));
const glow = 0.6 + P.energy*0.9;
const cloudA = (paper? 6 : 14) * (0.5 + P.density*1.3) * glow;
const beat = 0.85 + K.pulse*0.25 + A.mid*0.5;
const wkx = 0.9/ (dxc||1), wky = 1.3/(dyc||1);           // spatial wave numbers

push();
// ground
blendMode(BLEND); noStroke();
if (paper) { fill(38, 12, groundV); } else { fill(H, 30, groundV); }
rect(0,0,width,height);
translate(driftx, drifty);

const hexes = S.hex;
for (let h = 0; h < hexes.length; h++) {
  const hx = hexes[h], cx = hx.cx + hx.jx*jit, cy = hx.cy + hx.jy*jit;
  // aromaticity wave (two incommensurate) → local pi intensity
  const arB = 0.35 + 0.65*(0.5 + 0.5*Math.sin(cx*wkx + cy*wky - wt + hx.ph)) * (0.6 + 0.4*Math.sin(cx*wky*0.7 - cy*wkx*0.6 + wt*1.31));
  const m = 0.5 + 0.5*Math.sin(kek + hx.ph*0.5);         // Kekule morph A<->B

  // pi-electron cloud (fills interstices, lifts luminance)
  blendMode(paper ? BLEND : ADD);
  fill(cloud[0], cloud[1], cloud[2], Math.min(30, cloudA*arB*beat));
  ellipse(cx, cy, R*2.0, R*2.0);

  // sigma skeleton (hexagon outline)
  blendMode(paper ? BLEND : ADD);
  stroke(bond[0], bond[1], bond[2], bond[3]*glow);
  strokeWeight(bw); noFill();
  beginShape();
  for (let k = 0; k < 6; k++) vertex(cx + CA[k]*R, cy + SA[k]*R);
  endShape(CLOSE);

  // pi double-bond markers (resonance): triad A (edges 0,2,4) vs B (1,3,5)
  const inset = 0.72;
  for (let e = 0; e < 6; e++) {
    const aE = (e % 2 === 0) ? m : (1 - m);
    if (aE < 0.04) continue;
    const x1 = cx + CA[e]*R*inset, y1 = cy + SA[e]*R*inset;
    const n = (e+1)%6, x2 = cx + CA[n]*R*inset, y2 = cy + SA[n]*R*inset;
    stroke(bond[0], Math.min(100,bond[1]+15), Math.min(100,bond[2]+8), bond[3]*glow*aE);
    strokeWeight(bw*1.3); line(x1,y1,x2,y2);
  }

  // aromatic delocalization circle
  noFill(); stroke(arom[0], arom[1], arom[2], (paper?45:60)*arB*glow);
  strokeWeight(bw*0.9); ellipse(cx, cy, R*1.18, R*1.18);

  // carbons
  noStroke(); fill(carbon[0], carbon[1], carbon[2], (paper?70:85)*glow);
  for (let k = 0; k < 6; k++) ellipse(cx + CA[k]*R, cy + SA[k]*R, bw*2.4, bw*2.4);
}
pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
if (P.alpha < 100) { push(); noStroke(); fill(0,0,0,100-P.alpha); rect(0,0,width,height); pop(); }
